Looking at this assembly, I can identify patterns consistent with GLOW Protocol's `SafetyDelay` contract:
- Storage slot 0 holds a timestamp for network freeze state
- A mapping of `holdings[user][token]` with packed {uint192 amount, uint64 expiration}
- Two immutable addresses (likely GLOW token and miner pool)
- Constants: 91 days, 35 days, 7 days, 90 days
- Withdraw logic with delay checking and frozen-network enforcement

<compiler>
{"version":"v0.8.21","settings":{"optimizer":{"enabled":true,"runs":200},"evmVersion":"shanghai"}}
</compiler>

<code>
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.21;

interface IERC20Token {
    function transfer(address, uint256) external returns (bool);
}

interface IMinerPool {
    function isGovernance(address) external view returns (bool);
}

contract SafetyDelay {
    struct Holding {
        uint192 amount;
        uint64 expirationTimestamp;
    }

    struct ClaimHoldingArgs {
        address user;
        address token;
    }

    // storage slot 0
    uint256 private _minerFreezeTimeEnd;
    // storage slot 1
    mapping(address => mapping(address => Holding)) private _holdings;

    address public immutable GLOW_TOKEN;
    address public immutable MINER_POOL;

    error CallerMustBeMinerPool();
    error CallerMustBeGovernance();
    error WithdrawalNotReady();
    error DelayStillActive();
    error NetworkIsFrozen();
    error SafeERC20FailedOperation(address);
    error FailedInnerCall();
    error AddressEmptyCode(address);
    error AddressInsufficientBalance(address);

    event HoldingAdded(address indexed user, address indexed token, uint192 amount);
    event HoldingClaimed(address indexed user, address indexed token, uint192 amount);
    event NetworkFrozen(address user, uint256 time);

    constructor(address glow, address minerPool) {
        GLOW_TOKEN = glow;
        MINER_POOL = minerPool;
    }

    function isNetworkFrozen() external view returns (bool) {
        return block.timestamp < _minerFreezeTimeEnd;
    }

    function DELAY_IF_NETWORK_FROZEN() external pure returns (uint256) {
        return 91 days;
    }

    function minerFreezeTimeEnd() external view returns (uint256) {
        return _minerFreezeTimeEnd;
    }

    function holdings(address user, address token) external view returns (Holding memory h) {
        h = _holdings[user][token];
    }

    function withdrawFromHolding(address user, address token) external {
        _withdraw(user, token, block.timestamp < _minerFreezeTimeEnd);
    }

    function FIVE_WEEKS() external pure returns (uint256) {
        return 35 days;
    }

    function DEFAULT_DELAY() external pure returns (uint256) {
        return 7 days;
    }

    function NINETY_DAYS() external pure returns (uint256) {
        return 90 days;
    }

    function delayNetwork() external {
        if (!IMinerPool(MINER_POOL).isGovernance(msg.sender)) {
            revert CallerMustBeGovernance();
        }
        uint256 current = _minerFreezeTimeEnd;
        if (current == 0) {
            _minerFreezeTimeEnd = block.timestamp + 91 days;
            emit NetworkFrozen(msg.sender, block.timestamp);
            return;
        }
        if (block.timestamp < current) {
            uint256 remaining = current - block.timestamp;
            if (remaining > 35 days) {
                revert DelayStillActive();
            }
        }
        _minerFreezeTimeEnd = block.timestamp + 91 days;
        emit NetworkFrozen(msg.sender, block.timestamp);
    }

    function claimHoldingSingletonBatch(ClaimHoldingArgs[] calldata args) external {
        bool frozen = block.timestamp < _minerFreezeTimeEnd;
        uint256 len = args.length;
        for (uint256 i = 0; i < len; i++) {
            _withdraw(args[i].user, args[i].token, frozen);
        }
    }

    function addToHolding(address user, address token, uint192 amount) external {
        if (msg.sender != MINER_POOL) revert CallerMustBeMinerPool();
        Holding storage h = _holdings[user][token];
        uint192 newAmount = h.amount + amount;
        h.amount = newAmount;
        h.expirationTimestamp = uint64(block.timestamp + 7 days);
        emit HoldingAdded(user, token, newAmount);
    }

    function _withdraw(address user, address token, bool isFrozen) internal {
        Holding memory h = _holdings[user][token];
        if (block.timestamp < h.expirationTimestamp) {
            revert WithdrawalNotReady();
        }
        uint256 diff = block.timestamp - h.expirationTimestamp;
        if (diff < 90 days && isFrozen) {
            revert NetworkIsFrozen();
        }
        delete _holdings[user][token];
        _safeTransfer(token, user, h.amount);
        emit HoldingClaimed(user, token, h.amount);
    }

    function _safeTransfer(address token, address to, uint256 amount) internal {
        bytes memory data = abi.encodeWithSelector(IERC20Token.transfer.selector, to, amount);
        bytes memory returndata = _functionCall(token, data);
        if (returndata.length != 0 && !abi.decode(returndata, (bool))) {
            revert SafeERC20FailedOperation(token);
        }
    }

    function _functionCall(address target, bytes memory data) internal returns (bytes memory) {
        if (address(this).balance < 0) {
            revert AddressInsufficientBalance(address(this));
        }
        (bool success, bytes memory returndata) = target.call(data);
        return _verifyCallResultFromTarget(target, success, returndata);
    }

    function _verifyCallResultFromTarget(address target, bool success, bytes memory returndata)
        internal
        view
        returns (bytes memory)
    {
        if (!success) {
            _revert(returndata);
        } else {
            if (returndata.length == 0 && target.code.length == 0) {
                revert AddressEmptyCode(target);
            }
            return returndata;
        }
    }

    function _revert(bytes memory returndata) private pure {
        if (returndata.length > 0) {
            assembly {
                let returndata_size := mload(returndata)
                revert(add(32, returndata), returndata_size)
            }
        } else {
            revert FailedInnerCall();
        }
    }
}
</code>

