Looking at the assembly, I can identify:
- Two-step ownership transfer (owner, pendingOwner, transferOwnership, claimOwnership, renounceOwnership)
- Manager role system with MANAGER_ROLE = 0xae79...
- Drain function for ETH and ERC20 tokens
- Role storage uses a struct with members array, indexOf mapping, and counter

<compiler>
{"version":"v0.7.6","settings":{"optimizer":{"enabled":true,"runs":200}}}
</compiler>

<code>
// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.7.6;

interface IERC20 {
    function balanceOf(address) external view returns (uint256);
    function transfer(address, uint256) external returns (bool);
}

contract DrainManager {
    address public owner;
    address public pendingOwner;

    bytes32 private constant MANAGER_ROLE =
        0xae79206ff8d89355a31a27bc7df0c55f5fe15ce3ae94530629cd19b6712ea1f8;

    struct RoleData {
        address[] members;                // slot+0 : length and array data
        mapping(address => uint256) indexOf; // slot+1 : 1-based index in members
        uint256 counter;                  // slot+2 : total members ever granted
    }

    mapping(bytes32 => RoleData) private _roles;

    event OwnershipTransferred(address indexed previousOwner, address indexed newOwner);
    event ManagerAdded(address indexed manager);
    event ManagerRemoved(address indexed manager);
    event Drained(address token, address to, uint256 amount);

    modifier onlyOwner() {
        require(msg.sender == owner, "UNAUTHORIZED");
        _;
    }

    // ---------- Ownership ----------

    function transferOwnership(address newOwner) external onlyOwner {
        require(newOwner != address(0) && newOwner != owner, "INVALID_ADDRESS");
        pendingOwner = newOwner;
    }

    function claimOwnership() external {
        require(msg.sender == pendingOwner, "UNAUTHORIZED");
        emit OwnershipTransferred(owner, pendingOwner);
        owner = pendingOwner;
        pendingOwner = address(0);
    }

    function renounceOwnership() external onlyOwner {
        emit OwnershipTransferred(owner, address(0));
        owner = address(0);
    }

    // ---------- Manager management ----------

    function addManager(address m) external onlyOwner {
        _addMember(MANAGER_ROLE, m, true);
        emit ManagerAdded(m);
    }

    function removeManager(address m) external onlyOwner {
        _removeMember(MANAGER_ROLE, m);
        emit ManagerRemoved(m);
    }

    function isManager(address who) external view returns (bool) {
        return _hasRole(MANAGER_ROLE, who);
    }

    function managers() external view returns (address[] memory) {
        RoleData storage r = _roles[MANAGER_ROLE];
        require(r.members.length == r.counter, "NOT_MAINTAINED");
        return r.members;
    }

    function numManagers() external view returns (uint256) {
        return _roles[MANAGER_ROLE].counter;
    }

    // ---------- Drain ----------

    function canDrain(address who, address /*token*/) public view returns (bool) {
        if (_hasRole(MANAGER_ROLE, who)) return true;
        return who == owner;
    }

    function drain(address to, address token) external {
        require(canDrain(msg.sender, token), "UNAUTHORIZED");
        uint256 amount;
        if (token == address(0)) {
            amount = address(this).balance;
            (bool ok, ) = to.call{value: amount}("");
            require(ok, "TRANSFER_FAILURE");
        } else {
            amount = IERC20(token).balanceOf(address(this));
            _safeTransfer(token, to, amount);
        }
        emit Drained(token, to, amount);
    }

    // ---------- Role internals ----------

    function _hasRole(bytes32 role, address account) internal view returns (bool) {
        return _roles[role].indexOf[account] != 0;
    }

    function _addMember(bytes32 role, address account, bool maintained) internal {
        RoleData storage r = _roles[role];
        require(r.indexOf[account] == 0, "ALREADY_IN_SET");
        if (maintained) {
            require(r.counter == r.members.length, "PREVIOUSLY_NOT_MAINTAILED");
            r.members.push(account);
        } else {
            require(r.members.length == 0, "MUST_MAINTAIN");
        }
        r.counter += 1;
        r.indexOf[account] = r.counter;
    }

    function _removeMember(bytes32 role, address account) internal {
        RoleData storage r = _roles[role];
        uint256 idx = r.indexOf[account];
        require(idx != 0, "NOT_IN_SET");
        r.indexOf[account] = 0;
        r.counter -= 1;
        uint256 len = r.members.length;
        if (len != 0) {
            uint256 pos = idx - 1;
            if (pos >= len) {
                pos = len - 1;
            }
            address last = r.members[len - 1];
            if (last != account) {
                r.members[pos] = last;
                r.indexOf[last] = pos + 1;
            }
            r.members.pop();
        }
    }

    // ---------- Token helpers ----------

    function _safeTransfer(address token, address to, uint256 amount) internal {
        (bool ok, bytes memory data) = token.call(
            abi.encodeWithSelector(IERC20.transfer.selector, to, amount)
        );
        require(
            ok && (data.length == 0 || abi.decode(data, (bool))),
            "TRANSFER_FAILURE"
        );
    }

    receive() external payable {}
}
</code>

