        return _ownershipOf(tokenId);
    }

    function toLeaf(address a, uint256 b, uint256 c) public pure returns (bytes32) {
        return keccak256(abi.encodePacked(a, b, c));
    }

    function isPrivated(bytes32 leaf, bytes32[] calldata proof) public view returns (bool) {
        return MerkleProof.verify(proof, PRIVATE_ROOT, leaf);
    }

    function isWhiteListed(bytes32 leaf, bytes32[] calldata proof) public view returns (bool) {
        return MerkleProof.verify(proof, WHITELIST_ROOT, leaf);
    }

