        require(totalSupply() + amount <= MAX_SUPPLY, "Exceeds Max Supply");
        require(SALE_STEP == 3, "Public Sale is not opened");
        require(
            _numberMinted(msg.sender) + amount <= PUBLIC_MINT_LIMIT,
            "Exceeds mint limit per wallet"
        );
        _safeMint(msg.sender, amount);
    }

    function mintWhitelist(
        uint256 amount,
        uint256 maxA,
        uint256 maxB,
        bytes32[] calldata proof
    ) external {
        require(totalSupply() + amount <= MAX_SUPPLY, "Exceeds Max Supply");
        require(SALE_STEP == 2, "Whitelist Sale is not opened");
        require(isWhiteListed(toLeaf(msg.sender, maxA, maxB), proof), "Not whitelisted");
        require(
            _numberMinted(msg.sender) + amount <= maxB,
            "Exceeds mint limit per wallet"
        );
        _safeMint(msg.sender, amount);
    }

    function mintPrivate(
        uint256 amount,
        uint256 maxA,
        uint256 maxB,
        bytes32[] calldata proof
    ) external {
        require(totalSupply() + amount <= MAX_SUPPLY, "Exceeds Max Supply");
        require(SALE_STEP == 1, "Private Sale is not opened");
        require(isPrivated(toLeaf(msg.sender, maxA, maxB), proof), "Not whitelisted");
        require(
            _numberMinted(msg.sender) + amount <= maxB,
            "Exceeds mint limit per wallet"
        );
        _safeMint(msg.sender, amount);
    }

    function airdrop(address[] calldata recipients, uint256 amount) external onlyOwner {
        require(
            totalSupply() + amount * recipients.length <= MAX_SUPPLY,
            "Exceeds Max Supply"
        );
        for (uint256 i = 0; i < recipients.length; i++) {
            _safeMint(recipients[i], amount);
        }
    }

    // ============ Owner Setters ============

    function setBaseURI(string calldata uri) external onlyOwner {
        _baseURIExtended = uri;
    }

    function setUnrevealURI(string calldata uri) external onlyOwner {
        _unrevealURI = uri;
    }

    function setMaxSupply(uint256 v) external onlyOwner { MAX_SUPPLY = v; }
    function setSaleStep(uint256 v) external onlyOwner { SALE_STEP = v; }
    function setPublicMintLimit(uint256 v) external onlyOwner { PUBLIC_MINT_LIMIT = v; }
    function setPrivateRoot(bytes32 v) external onlyOwner { PRIVATE_ROOT = v; }
    function setWhitelistRoot(bytes32 v) external onlyOwner { WHITELIST_ROOT = v; }

    function withdraw() external onlyOwner {
        (bool success, ) = payable(msg.sender).call{value: address(this).balance}("");
        require(success);
    }

    receive() external payable {}
}
