    function _burnBasket(uint256 amount) internal returns (address[] memory, uint256[] memory) {
        (address[] memory assets, ) = IBDPI(BDPI).getAssetsAndBalances();
        uint256[] memory balBefore = new uint256[](assets.length);
        for (uint256 i = 0; i < assets.length; i++) {
            balBefore[i] = IERC20(assets[i]).balanceOf(address(this));
        }
        IBDPI(BDPI).burn(amount);
        uint256[] memory diffs = new uint256[](assets.length);
        address[] memory tokens = new address[](assets.length);
        for (uint256 i = 0; i < assets.length; i++) {
