        uint256 reserveOut = token0 == from ? uint256(r1) : uint256(r0);
        uint256 amountInWithFee = _mul(amountIn, 997);
        uint256 amountOut = _mul(amountInWithFee, reserveOut) / _add(_mul(reserveIn, 1000), amountInWithFee);
