contract SmartWallet {
    address public owner;
    address public pendingOwner;
    mapping(address => uint16) public recoveryDelaysInDays;
    address public activeRecoveryAddress;
    uint256 public activeRecoveryEndTime;

    event RecoveryAddressAdded(address indexed recoveryAddress, uint16 delay);
    event RecoveryAddressRemoved(address indexed recoveryAddress);
    event RecoveryStarted(address indexed recoveryAddress);
    event RecoveryCancelled(address indexed recoveryAddress);
    event RecoveryFinished(address indexed newOwner);
    event OwnershipTransferStarted(address indexed previousOwner, address indexed newOwner);
    event OwnershipTransferCancelled(address indexed previousOwner, address indexed pendingOwner);
    event OwnershipTransferFinished(address indexed previousOwner, address indexed newOwner);

    modifier onlyOwner() {
        require(msg.sender == owner, "Only the owner may call this method.");
        _;
    }

    modifier whenNotInRecovery() {
        require(activeRecoveryAddress == address(0), "This method cannot be called during a recovery.");
        _;
    }

    modifier whenInRecovery() {
        require(activeRecoveryAddress != address(0), "This method can only be called during a recovery.");
        _;
    }

    constructor() public {
        owner = msg.sender;
    }

    function() external payable {}

    function execute(address payable destination, uint256 value, bytes calldata data)
        external
        onlyOwner
        whenNotInRecovery
        returns (bytes memory)
    {
        require(
            destination != address(0),
            "Transaction execution must contain a destination.  If you meant to deploy a contract, use deploy instead."
        );
        require(
            address(this).balance >= value,
            "Wallet does not have enough funds available to execute the desired transaction."
        );
        (bool success, bytes memory result) = destination.call.value(value)(data);
        require(success, "Contract execution failed.");
        return result;
    }

    function deploy(uint256 value, bytes calldata code, uint256 salt)
        external
        onlyOwner
        whenNotInRecovery
        returns (address)
    {
        require(
            address(this).balance >= value,
            "Wallet does not have enough funds available to deploy the contract."
        );
        require(code.length > 0, "Contract deployment must contain bytecode.");
        address deployed;
        bytes memory c = code;
        assembly {
            deployed := create2(value, add(c, 0x20), mload(c), salt)
        }
        require(deployed != address(0), "Contract creation returned address 0, indicating failure.");
        return deployed;
    }

    function addRecoveryAddress(address recovery, uint16 delayInDays)
        external
        onlyOwner
        whenNotInRecovery
    {
        require(recovery != address(0), "Recovery address must be supplied.");
        require(delayInDays > 0, "Recovery delay must be at least 1 day.");
        recoveryDelaysInDays[recovery] = delayInDays;
        emit RecoveryAddressAdded(recovery, delayInDays);
    }

    function removeRecoveryAddress(address recovery)
        public
        onlyOwner
        whenNotInRecovery
    {
        require(recovery != address(0), "Recovery address must be supplied.");
        delete recoveryDelaysInDays[recovery];
        emit RecoveryAddressRemoved(recovery);
    }

    function startOwnershipTransfer(address newOwner) external onlyOwner {
        require(newOwner != address(0), "Contract must have an owner.");
        if (pendingOwner != address(0)) {
            _cancelOwnershipTransfer();
        }
        pendingOwner = newOwner;
        emit OwnershipTransferStarted(owner, newOwner);
    }

    function cancelOwnershipTransfer() external onlyOwner {
        _cancelOwnershipTransfer();
    }

    function _cancelOwnershipTransfer() internal {
        require(pendingOwner != address(0), "There is no pending transfer to be cancelled.");
        emit OwnershipTransferCancelled(owner, pendingOwner);
        pendingOwner = address(0);
    }

    function acceptOwnership() external {
        require(msg.sender == pendingOwner, "Only the pending owner can call this method.");
        address previousOwner = owner;
        owner = pendingOwner;
        pendingOwner = address(0);
        emit OwnershipTransferFinished(previousOwner, owner);
    }

    function startRecovery() external {
        uint16 newDelay = recoveryDelaysInDays[msg.sender];
        require(newDelay > 0, "Only designated recovery addresses can initiate the recovery process.");
        if (activeRecoveryAddress != address(0)) {
            uint16 currentDelay = recoveryDelaysInDays[activeRecoveryAddress];
            require(
                newDelay < currentDelay,
                "Recovery is already underway and new recovery doesn't have a higher priority."
            );
            emit RecoveryCancelled(activeRecoveryAddress);
        }
        activeRecoveryAddress = msg.sender;
        activeRecoveryEndTime = block.timestamp + uint24(uint256(newDelay) * 1 days);
        emit RecoveryStarted(msg.sender);
    }

    function cancelRecovery() public onlyOwner whenInRecovery {
        emit RecoveryCancelled(activeRecoveryAddress);
        _endRecovery();
    }

    function cancelRecoveryAndRemoveRecoveryAddress() external onlyOwner whenInRecovery {
        address recovery = activeRecoveryAddress;
        cancelRecovery();
        removeRecoveryAddress(recovery);
    }

    function finishRecovery() external whenInRecovery {
        require(
            block.timestamp > activeRecoveryEndTime,
            "You must wait until the recovery delay is over before finishing the recovery."
        );
        address previousOwner = owner;
        owner = activeRecoveryAddress;
        _endRecovery();
        emit RecoveryFinished(owner);
        emit OwnershipTransferStarted(previousOwner, owner);
        emit OwnershipTransferFinished(previousOwner, owner);
    }

    function _endRecovery() internal {
        activeRecoveryAddress = address(0);
        activeRecoveryEndTime = uint256(-1);
    }

    function tokensReceived(
        address,
        address,
        address,
        uint256,
        bytes calldata,
        bytes calldata
    ) external {
    }

    function canImplementInterfaceForAddress(bytes32 interfaceHash, address addr)
        external
        view
        returns (bytes32)
    {
        if (addr == address(this) && interfaceHash == keccak256("ERC777TokensRecipient")) {
            return keccak256("ERC1820_ACCEPT_MAGIC");
        }
        return bytes32(0);
    }
}
