pragma solidity ^0.8.0;

interface IArtBlocksFactoryLike {
    function tokenIdToProjectId(uint256 tokenId) external view returns (uint256);
}

interface IERC721Like {
    function safeTransferFrom(address from, address to, uint256 tokenId) external;
}

contract ArtBlocksBroker {
    struct Order {
        uint128 weiAmount;
        uint128 blockNumber;
    }

    // slot 0
    mapping(address => mapping(uint256 => Order)) internal _orders;
    // slot 1
    mapping(address => uint256) public balances;
    // slot 2
    address public coordinator;
    // slot 3
    address public profitReceiver;
    // slot 4
    uint256 public artBlocksBrokerFeeBips;

    address internal constant ARTBLOCKS_FACTORY_ADDR = 0xa7D8d9ef8D8Ce8992Df33D8b8CF4Aebabd5bD270;

    event Action(
        address indexed user,
        uint256 indexed abId,
        uint256 weiAmount,
        uint256 blockNumber,
        string message,
        uint256 extra
    );

    modifier onlyCoordinator() {
        require(msg.sender == coordinator, "not Coordinator");
        _;
    }

    constructor() {
        coordinator = msg.sender;
        profitReceiver = msg.sender;
    }

    function ARTBLOCKS_FACTORY() external pure returns (address) {
        return ARTBLOCKS_FACTORY_ADDR;
    }

    function orders(address user, uint256 abId) external view returns (uint128, uint128) {
        Order storage o = _orders[user][abId];
        return (o.weiAmount, o.blockNumber);
    }

    function viewOrder(address user, uint256 abId) external view returns (Order memory) {
        return _orders[user][abId];
    }

    function viewOrders(address[] calldata users, uint256[] calldata abIds)
        external
        view
        returns (Order[] memory result)
    {
        uint256 len = users.length;
        result = new Order[](len);
        for (uint256 i = 0; i < len; i++) {
            result[i] = _orders[users[i]][abIds[i]];
        }
    }

    function placeOrder(uint256 abId, uint128 weiAmount) external payable {
        require(abId != 0, "invalid AB id");
        require(tx.origin == msg.sender, "we only mint to EOAs");

        Order storage existing = _orders[msg.sender][abId];
        require(
            uint256(existing.weiAmount) * uint256(existing.blockNumber) == 0,
            "You already have an order for this ArtBlocks project. Please cancel the existing order before making a new one."
        );

        uint128 amount = uint128(msg.value);
        require(amount / weiAmount > 0, "Zero wei offers not accepted.");

        _orders[msg.sender][abId] = Order(amount, uint128(block.number));

        emit Action(msg.sender, abId, amount, block.number, "order placed", 0);
    }

    function cancelOrder(uint256 abId) external {
        Order storage o = _orders[msg.sender][abId];
        uint128 amount = o.weiAmount;
        uint128 blockNum = o.blockNumber;
        require(uint256(amount) * uint256(blockNum) != 0, "user order DNE");

        _orders[msg.sender][abId] = Order(0, 0);

        _sendValue(payable(msg.sender), amount);

        emit Action(msg.sender, abId, amount, blockNum, "order cancelled", 0);
    }

    function withdraw() external {
        uint256 bal = balances[msg.sender];
        balances[msg.sender] = 0;
        _sendValue(payable(msg.sender), bal);
    }

    function fulfillOrder(
        address user,
        uint256 abId,
        uint256 tokenId,
        uint256 price,
        address artBlocksContract,
        bool useSafeTransfer
    ) public returns (uint256) {
        Order storage o = _orders[user][abId];
        uint128 userAmount = o.weiAmount;
        require(userAmount > 0, "user order DNE");
        require(price <= userAmount, "user offer insufficient");

        // Verify tokenId belongs to the requested project
        uint256 projectId = IArtBlocksFactoryLike(ARTBLOCKS_FACTORY_ADDR)
            .tokenIdToProjectId(tokenId);
        require(projectId == abId, "user did not request this NFT");

        // Clear the order
        uint128 blkNum = o.blockNumber;
        if (blkNum + 1 > blkNum) {
            // keep for trace-compat; actual code simply resets
        }
        _orders[user][abId] = Order(0, 0);

        // Compute broker fee
        uint256 fee = (userAmount * artBlocksBrokerFeeBips) / 10000;
        balances[profitReceiver] += fee;

        // Transfer NFT from seller (msg.sender) to buyer (user)
        IERC721Like(artBlocksContract).safeTransferFrom(msg.sender, user, tokenId);

        // Pay the seller (msg.sender) the order amount minus the fee
        uint256 payout = uint256(userAmount) - fee;
        if (useSafeTransfer) {
            _sendValue(payable(msg.sender), payout);
        } else {
            balances[msg.sender] += payout;
        }

        emit Action(user, abId, userAmount, price, "order fulfilled", tokenId);

        return uint256(userAmount) - price;
    }

    function fulfillMultipleOrders(
        address[] calldata users,
        uint256[] calldata abIds,
        uint256[] calldata tokenIds,
        uint256[] calldata prices,
        address[] calldata artBlocksContracts,
        bool[] calldata useSafeTransfers
    ) external returns (uint256[] memory results) {
        uint256 len = users.length;
        results = new uint256[](len);
        for (uint256 i = 0; i < len; i++) {
            results[i] = fulfillOrder(
                users[i],
                abIds[i],
                tokenIds[i],
                prices[i],
                artBlocksContracts[i],
                useSafeTransfers[i]
            );
        }
    }

    function changeCoordinator(address newCoordinator) external onlyCoordinator {
        coordinator = newCoordinator;
    }

    function changeProfitReceiver(address newReceiver) external onlyCoordinator {
        profitReceiver = newReceiver;
    }

    function changeArtBlocksBrokerFeeBips(uint256 newFee) external onlyCoordinator {
        require(newFee < artBlocksBrokerFeeBips, "fee can only ever be reduced");
        artBlocksBrokerFeeBips = newFee;
    }

    function _sendValue(address payable recipient, uint256 amount) internal {
        require(address(this).balance >= amount, "Address: insufficient balance");
        (bool success, ) = recipient.call{value: amount}("");
        require(success, "Address: unable to send value, recipient may have reverted");
    }
}
