        uint256 value,
        uint256 amount,
        uint256 bonus,
        uint256 rateSnapshot,
        uint256 totalMinted
    );

    constructor(
        address _token,
        uint256 _startTime,
        uint256 _endTime,
        uint256 _rate,
        address _fundAddress,
        address _fundAddress2,
        uint256 _minimumSupply
    ) public {
        require(_token != address(0));
        require(_fundAddress != address(0));
        require(_fundAddress2 != address(0));
        require(_startTime >= now);
        require(_endTime >= _startTime);

        token = MintableToken(_token);
        startTime = _startTime;
        endTime = _endTime;
        discountEndTime = _startTime;
        rate = _rate;
        fundAddress = _fundAddress;
        fundAddress2 = _fundAddress2;
        minimumSupply = _minimumSupply;
        isRunning = true;
        isDiscount = true;
        contractStatus = "Discount sale";
    }

    function name() public pure returns (string) {
        return "National Money Contract";
    }

