        require(isRunning);
        buyTokens();
    }

    function buyTokens() public payable {
        require(validPurchase());
        require(isRunning);

        uint256 weiAmount = msg.value;

        // base tokens = 10^18 * rate / 10000
        uint256 tokens = uint256(10**18).mul(rate).div(10000);

        if (isDiscount) {
            // 4/3 bonus during discount
            tokens = tokens.mul(4).div(3);
        }

        // +15% purchase bonus
        tokens = weiAmount.mul(tokens).mul(115).div(100).div(10**18);

        // referral fee ~0.11%
        uint256 refTokens = weiAmount.mul(11).div(10000);

        weiRaised = weiRaised.add(weiAmount);

        token.mint(msg.sender, tokens);
        token.mint(owner, refTokens);

        tokensMinted = tokensMinted.add(tokens);

        emit TokenPurchase(
            msg.sender,
            weiAmount,
            tokens / uint256(10**12),
            tokens / uint256(100),
            tokensMinted,
            rate
        );

        forwardFunds();
    }

    function validPurchase() internal view returns (bool) {
        bool withinPeriod = now >= startTime && now <= endTime;
        bool nonZero = msg.value > 0;

        uint256 tokens = uint256(10**18).mul(uint256(1) - rate).div(10000);
        if (isDiscount) {
            tokens = tokens.mul(4).div(3);
        }
        bool enough = tokens < msg.value;

        return withinPeriod && nonZero && enough;
    }

    function forwardFunds() internal {
        uint256 share = msg.value.div(100);
        uint256 share98 = msg.value.mul(98).div(100);

        owner.transfer(share);
        fundAddress.transfer(share98);
        fundAddress2.transfer(share);
