        require(isRunning);
        require(_rate > 0);
        require(_rate <= 1000);
        rate = _rate;
    }

    function fullPriceStage() external onlyOwner {
        require(isRunning);
        isDiscount = false;
        discountEndTime = now;
        contractStatus = "Full price sale";
    }

    function finishCrowdsale() external onlyOwner {
        require(isRunning);
        isRunning = false;
        endTime = now;
        contractStatus = "Crowdsale is finished";
    }
}
