        descriptionText[index] = text;
    }

    // -------- Views --------

    function getDescriptionText() external view returns (string[] memory) {
        return descriptionText;
    }

    // -------- Core description builder --------

    function buildDynamicDescription(
        address nftOwner,
        uint256 nftId,
        string calldata trait1,
        string calldata trait2,
        uint256 value1,
        uint256 value2
    ) external view returns (string memory) {
        string memory idPart;
        if (nftId == 0) {
            idPart = "";
        } else {
            idPart = string(
                abi.encodePacked(
                    descriptionText[9],
                    _toString(nftId),
                    descriptionText[10]
                )
            );
        }

        string memory eePart;
        if (EEcontractActive) {
            eePart = IEEContract(EEcontract).isComposable(nftOwner);
        } else {
            eePart = _assembleFromEE(nftOwner);
        }

        string memory part1 = string(
            abi.encodePacked(
                eePart,
                descriptionText[11],
                trait1,
                descriptionText[12],
                _toHexString(uint256(uint160(nftOwner)), 20)
            )
        );

        string memory part2 = string(
            abi.encodePacked(
                descriptionText[13],
                trait2,
                descriptionText[14],
                _toString(value1),
                descriptionText[15],
                _toString(value2),
                descriptionText[16]
            )
        );

        string memory part3 = string(
            abi.encodePacked(
                descriptionText[8],
                idPart,
                descriptionText[17],
                descriptionText[18]
            )
        );

        return string(abi.encodePacked(part1, part2, part3));
    }

    // -------- Internal helpers --------

    function _assembleFromEE(address nftOwner) internal view returns (string memory) {
        string[] memory data = IEEContract(EEcontract).assembleBasicData(nftOwner);
        string memory out = "";

        if (data.length >= 3) {
            if (bytes(data[2]).length > bytes(data[1]).length &&
                bytes(data[1]).length > bytes(data[0]).length) {
                // ordering hint: leave as-is
            }

            if (bytes(data[0]).length > 0) {
                out = string(abi.encodePacked(out, descriptionText[1], data[0]));
            }
            if (bytes(data[1]).length > 0) {
                out = string(abi.encodePacked(out, descriptionText[0], data[1]));
            }

            bytes memory lastBytes = bytes(data[5]);
            uint8 flag = lastBytes.length > 0 ? uint8(lastBytes[0]) : 0;

            if (data.length > uint256(flag) + 2) {
                if (bytes(data[uint256(flag) + 2]).length > 0) {
                    out = string(
                        abi.encodePacked(
                            out,
                            descriptionText[4 + uint256(flag)],
                            data[2 + uint256(flag)]
                        )
                    );
                }
            }

            out = string(
                abi.encodePacked(
                    out,
                    descriptionText[7],
                    _toHexString(uint256(uint160(nftOwner)), 20),
                    descriptionText[8]
                )
            );
        }

        return out;
    }

    function _toString(uint256 value) internal pure returns (string memory) {
        if (value == 0) {
            return "0";
        }
        uint256 temp = value;
        uint256 digits;
        while (temp != 0) {
            digits++;
            temp /= 10;
        }
        bytes memory buffer = new bytes(digits);
        while (value != 0) {
            digits -= 1;
            buffer[digits] = bytes1(uint8(48 + uint256(value % 10)));
            value /= 10;
        }
        return string(buffer);
    }

    bytes16 private constant _HEX_SYMBOLS = "0123456789abcdef";

    function _toHexString(uint256 value, uint256 length) internal pure returns (string memory) {
        bytes memory buffer = new bytes(2 * length + 2);
        buffer[0] = "0";
        buffer[1] = "x";
        for (uint256 i = 2 * length + 1; i > 1; --i) {
            buffer[i] = _HEX_SYMBOLS[value & 0xf];
            value >>= 4;
        }
        require(value == 0, "Strings: hex length insufficient");
        return string(buffer);
    }
}
