contract ProofPresale {
    // --- Storage layout (packed by Solidity) ---
    // slot 0
    address public owner;
    bool public paused;
    // slot 1
    IProofToken public proofToken;
    // slot 2
    uint256 public totalWeiRaised;
    // slot 3
    uint256 public tokensMinted;
    // slot 4 (reserved / unused)
    uint256 private _reserved4;
    // slot 5
    uint256 public contributors;
    // slot 6
    uint256 public decimalsMultiplier;
    // slot 7
    uint256 public startTime;
    // slot 8
    uint256 public endTime;
    // slot 9
    uint256 public remainingTokens;
    // slot 10 (0xa) - exposed via selector 0x002f9569
    uint256 public presaleVar;
    // slot 11 (0xb) - packed
    bool public finalized;
    bool public proofTokensAllocated;
    address public proofMultiSig;
    // slots 12-20
    uint256 public tokenCap;
    uint256 public cap;
    uint256 public weiCap;
    uint256 public firstDiscountPrice;
    uint256 public secondDiscountPrice;
    uint256 public thirdDiscountPrice;
    uint256 public firstDiscountCap;
    uint256 public secondDiscountCap;
    uint256 public thirdDiscountCap;
    // slot 21
    bool public started;

    // --- Constants ---
    uint256 public constant BASE_PRICE_IN_WEI = 0x0138a388a43c0000;
    uint256 public constant TOKENS_ALLOCATED_TO_PROOF = 0xfa17d19cc9954d3c0000;
    uint256 public constant TOTAL_PRESALE_TOKENS = 0x17cc7ef452b682538760;

    // --- Events ---
    event TokenPurchase(address indexed purchaser, address indexed beneficiary, uint256 value, uint256 amount);
    event Pause();
    event Unpause();
    event Finalized();

    modifier onlyOwner() {
        require(msg.sender == owner);
        _;
    }

    function ProofPresale() public {
        owner = msg.sender;
    }

    function () public payable {
        buyTokens(msg.sender);
    }

    // Alias: TOKENS_ALLOCATED_TO_PROOF and PUBLIC_TOKENS return the same constant
    function PUBLIC_TOKENS() public pure returns (uint256) {
        return TOKENS_ALLOCATED_TO_PROOF;
    }

    function buyTokens(address beneficiary) public payable {
        require(!paused);
        require(!finalized);
        require(beneficiary != address(0));
        require(validPurchase());

        uint256 weiAmount = msg.value;
        uint256 priceInWei = getPriceInWei();

        totalWeiRaised = safeAdd(totalWeiRaised, weiAmount);
        uint256 tokenAmount = safeDiv(safeMul(weiAmount, decimalsMultiplier), priceInWei);
        tokensMinted = safeAdd(tokensMinted, tokenAmount);
        require(tokensMinted < tokenCap);

        contributors = safeAdd(contributors, 1);

        proofToken.mint(beneficiary, tokenAmount);
        TokenPurchase(msg.sender, beneficiary, weiAmount, tokenAmount);

        forwardFunds();
    }

    function forwardFunds() internal {
        require(proofMultiSig.call.value(msg.value)());
    }

    function validPurchase() internal view returns (bool) {
        bool withinPeriod = (block.timestamp >= startTime || started) && block.timestamp <= endTime;
        bool nonZeroPurchase = msg.value != 0;
        return withinPeriod && nonZeroPurchase;
    }

    function getPriceInWei() public view returns (uint256) {
        if (totalWeiRaised < firstDiscountCap)  return firstDiscountPrice;
        if (totalWeiRaised < secondDiscountCap) return secondDiscountPrice;
        if (totalWeiRaised < thirdDiscountCap)  return thirdDiscountPrice;
        return BASE_PRICE_IN_WEI;
    }

    function totalSupply() public view returns (uint256) {
        return proofToken.totalSupply();
    }

    function balanceOf(address _owner) public view returns (uint256) {
        return proofToken.balanceOf(_owner);
    }

    function changeController(address _newController) public onlyOwner {
        proofToken.transferControl(_newController);
    }

    function enableMasterTransfers() public onlyOwner {
        proofToken.enableMasterTransfers(true);
    }

    function lockMasterTransfers() public onlyOwner {
        proofToken.enableMasterTransfers(false);
    }

    function enableTransfers() public {
        require(block.timestamp > endTime || msg.sender == owner);
        proofToken.enableTransfers(true);
    }

    function lockTransfers() public onlyOwner {
        require(block.timestamp > endTime);
        proofToken.enableTransfers(false);
    }

    function pause() public onlyOwner {
        require(!paused);
        paused = true;
        Pause();
    }

    function unpause() public onlyOwner {
        require(paused);
        paused = false;
        Unpause();
    }

    function finalize() public onlyOwner {
        require(paused);
        require(proofTokensAllocated);

        proofToken.finishMinting();
        proofToken.enableTransfers(true);

        Finalized();
        finalized = true;
    }

    function allocateProofTokens() public onlyOwner {
        require(!finalized);
        require(!proofTokensAllocated);

        proofToken.mint(proofMultiSig, TOKENS_ALLOCATED_TO_PROOF);
        proofTokensAllocated = true;
    }

    function forceStart() public onlyOwner {
        started = true;
    }

    function transferOwnership(address newOwner) public onlyOwner {
        if (newOwner != address(0)) {
            owner = newOwner;
        }
    }

    // --- SafeMath helpers ---
    function safeAdd(uint256 a, uint256 b) internal pure returns (uint256) {
        uint256 c = a + b;
        assert(c >= a);
        return c;
    }

    function safeMul(uint256 a, uint256 b) internal pure returns (uint256) {
        if (a == 0) {
            return 0;
        }
        uint256 c = a * b;
        assert(c / a == b);
        return c;
    }

    function safeDiv(uint256 a, uint256 b) internal pure returns (uint256) {
        require(b > 0);
        return a / b;
    }
}
