    uint8 public constant _gearboxAdapterType = 0;

    modifier onlyMigratorBot() {
        require(
            msg.sender == migratorBot,
            "MigratorAdapter: caller is not the migrator bot"
        );
        _;
    }

    constructor(
        address _creditManager,
        address _targetContract,
        address _acl,
        address _migratorBot
    ) {
        creditManager = _creditManager;
        targetContract = _targetContract;
        acl = _acl;
        migratorBot = _migratorBot;
    }

    function version() external pure returns (uint256) {
        revert NotImplemented();
    }

    function contractType() external pure returns (bytes32) {
        revert NotImplemented();
    }

    function lock() external onlyMigratorBot {
        require(!locked, "MigratorAdapter: adapter is already locked");
        locked = true;
    }

    function unlock() external onlyMigratorBot {
        require(locked, "MigratorAdapter: adapter is not locked");
        locked = false;
    }

    function serialize() external view returns (bytes memory) {
        return abi.encode(creditManager, targetContract);
    }

    function migrate(MigrationData calldata data)
        external
        returns (uint256 tokensToEnable, uint256 tokensToDisable)
    {
        require(!locked, "MigratorAdapter: adapter is locked");

        address facade = ICreditManagerV3(creditManager).creditFacade();
        if (msg.sender != facade) revert CallerNotCreditFacadeException();

        _approveAll(data, type(uint256).max);
        ICreditFacadeV3(creditManager).execute(msg.data);
        _approveAll(data, 0);

        return (0, type(uint256).max);
    }

    function _approveAll(MigrationData calldata data, uint256 mode) internal {
        uint256 len = data.tokens.length;
        for (uint256 i = 0; i < len; i++) {
            address token;
            if (mode == type(uint256).max) {
                token = data.tokens[i].token;
            } else {
                token = data.tokens[i].data.target;
            }
            ITargetContract(targetContract).approveCreditAccount(token, mode);
        }
    }
