        address old = _owner;
        _owner = newOwner;
        emit OwnershipTransferred(old, newOwner);
    }
}

contract DropManager is OwnableUpgradeable {
    struct Drop {
        uint256 dropId;        // slot 0
        uint256 counter;       // slot 1 (incremented by NFT contract)
        uint256 royaltyAmount; // slot 2 (set by setRightHolderInfo)
        uint256 price;         // slot 3 (updateDropPrice)
        uint256 supply;        // slot 4 (updateDropSupply)
        uint256 royaltyShare;  // slot 5 (updateDropRoyaltyShare)
        address rightHolder;   // slot 6 (setRightHolderInfo)
        address nft;           // slot 7 (setDropNFT)
    }

    Drop[] private _drops;        // slot 101 (0x65)
    uint256 private _packed;       // slot 102 (0x66): [treasury(160b, bits 32..191)] [gasLimit(uint32, bits 0..31)]
    address private _addrSlot67;   // slot 103
    address private _addrSlot68;   // slot 104

    error ZeroAddress();
    error InsufficientRoyalties();
    error UnauthorizedUpdate();
    error AmountCannotBeZero();
    error InvalidGasLimit();

    event DropCreated(uint256 dropId);

    function initialize(address a, address b, address t) external initializer {
        if (a == address(0)) revert ZeroAddress();
        if (b == address(0)) revert ZeroAddress();
        if (t == address(0)) revert ZeroAddress();

        __Ownable_init();

        _addrSlot67 = a;
        _addrSlot68 = b;
        _packed = (uint256(uint160(t)) << 32) | uint256(1500000);

        _seedDefaults();
    }

    function _seedDefaults() internal {
        address defaultNft = 0x7BeD83806F969942431825588B6bD389a3CeDF75;
        uint256[3] memory prices = [
            uint256(50000000000000000),
            uint256(85000000000000000),
            uint256(70000000000000000)
        ];
        uint256[3] memory supplies = [uint256(250), uint256(400), uint256(500)];
        uint256[3] memory royaltyAmounts = [uint256(200), uint256(25), uint256(10)];
        uint256[3] memory royaltyShares = [uint256(1000000), uint256(0), uint256(0)];

        for (uint256 i = 0; i < 3; i++) {
            _drops.push(
                Drop({
                    dropId: _drops.length,
                    counter: 0,
                    royaltyAmount: royaltyAmounts[i],
                    price: prices[i],
                    supply: supplies[i],
                    royaltyShare: royaltyShares[i],
                    rightHolder: address(0),
                    nft: defaultNft
                })
            );
            emit DropCreated(_drops.length - 1);
        }
    }

    function treasury() external view returns (address) {
        return address(uint160(_packed >> 32));
    }

    function drops(uint256 id)
        external
        view
        returns (
            uint256,
            uint256,
            uint256,
            uint256,
            uint256,
            uint256,
            address,
            address
        )
    {
        Drop storage d = _drops[id];
        return (
            d.dropId,
            d.counter,
            d.royaltyAmount,
            d.price,
            d.supply,
            d.royaltyShare,
            d.rightHolder,
            d.nft
        );
    }

    function updateDropPrice(uint256 id, uint256 newPrice) external onlyOwner {
        _drops[id].price = newPrice;
        emit DropCreated(id);
    }

    function updateDropSupply(uint256 id, uint256 newSupply) external onlyOwner {
        if (newSupply == 0) revert AmountCannotBeZero();
        if (_drops[id].counter > newSupply) revert UnauthorizedUpdate();
        _drops[id].supply = newSupply;
        emit DropCreated(id);
    }

    function setDropNFT(uint256 id, address nft) external onlyOwner {
        if (nft == address(0)) revert ZeroAddress();
        _drops[id].nft = nft;
    }

    function setGasLimit(uint32 newLimit) external onlyOwner {
        if (newLimit == 0) revert InvalidGasLimit();
        _packed = (_packed & ~uint256(type(uint32).max)) | uint256(newLimit);
    }

    function updateDropRoyaltyShare(uint256 id, uint256 newShare) external onlyOwner {
        if (newShare == 0) revert InsufficientRoyalties();
        _drops[id].royaltyShare = newShare;
        emit DropCreated(id);
    }

    function updateDropCounter(uint256 id, uint256 delta) external {
        Drop storage d = _drops[id];
        if (d.nft != msg.sender) revert UnauthorizedUpdate();
        d.counter = d.counter + delta;
    }

    function setRightHolderInfo(
        uint256 id,
        uint256 amount,
        address holder
    ) external onlyOwner {
        if (holder == address(0)) revert ZeroAddress();
        Drop storage d = _drops[id];
        d.royaltyAmount = amount;
        d.rightHolder = holder;
        emit DropCreated(id);
    }

    function updateOnTransfer(
        address,
        address,
        uint256,
        uint256
    ) external {
        // no-op
    }

    function setTreasury(address newTreasury) external onlyOwner {
        if (newTreasury == address(0)) revert ZeroAddress();
        uint256 mask = ~(((uint256(1) << 160) - 1) << 32);
        _packed = (_packed & mask) | (uint256(uint160(newTreasury)) << 32);
    }

    function create(
        address rightHolder,
        uint256 price,
        uint256 supply,
        uint256 royaltyAmount,
        uint256 royaltyShare,
        int96 /*flowRate*/,
        address nft
    ) external onlyOwner {
        if (price == 0) revert InsufficientRoyalties();
        if (supply == 0) revert AmountCannotBeZero();
        if (rightHolder == address(0)) revert ZeroAddress();
        if (nft == address(0)) revert ZeroAddress();

        address t = address(uint160(_packed >> 32));
        ITreasury(t).setDropId(_drops.length);

        _drops.push(
            Drop({
                dropId: _drops.length,
                counter: 0,
                royaltyAmount: royaltyAmount,
                price: price,
                supply: supply,
                royaltyShare: royaltyShare,
                rightHolder: rightHolder,
                nft: nft
            })
        );
        emit DropCreated(_drops.length - 1);
    }
}
