contract ProtectionStaking is Ownable, ReentrancyGuard {
    using SafeMath for uint256;
    using SafeERC20 for IERC20;

    IERC20 public sharesToken;          // slot 1
    IFund public fund;                  // slot 2
    IERC20 public peakToken;            // slot 3
    IUniswapOracle public uniswapOracle;// slot 4
    uint256 public mintedPeakTokens;    // slot 5
    uint256 public peakMintCap;         // slot 6

    mapping(address => uint256) public peaks;                  // slot 7
    mapping(address => uint256) public shares;                 // slot 8
    mapping(address => uint256) public startProtectTimestamp;  // slot 9
    mapping(address => uint256) internal startClaimTimestamp;  // slot 10
    mapping(address => uint256) public lastClaimAmount;        // slot 11

    uint256 internal constant PEAK_PRECISION = 1e8;
    uint256 internal constant SHARE_PRECISION = 1e8;
    uint256 internal constant MAX_SHARE_VALUE = 100000 * 1e18;

    event ChangePeakMintCap(uint256 newCap);
    event Withdraw(address sender, uint256 amount, uint256 timestamp);
    event WithdrawShares(address sender, uint256 amount, uint256 timestamp);
    event ProtectShares(address sender, uint256 amount, uint256 timestamp);
    event RequestProtection(address sender, uint256 amount, uint256 timestamp);
    event ClaimCompensation(address sender, uint256 amount, uint256 timestamp);

    constructor(
        address _sharesToken,
        address _fund,
        address _peakToken,
        address _uniswapOracle,
        uint256 _peakMintCap
    ) public {
        sharesToken = IERC20(_sharesToken);
        fund = IFund(_fund);
        peakToken = IERC20(_peakToken);
        uniswapOracle = IUniswapOracle(_uniswapOracle);
        peakMintCap = _peakMintCap;
    }

    function setPeakMintCap(uint256 amount) public onlyOwner {
        require(amount >= mintedPeakTokens, "wrong amount");
        peakMintCap = amount;
        emit ChangePeakMintCap(amount);
    }

    function protectShares(uint256 amount) public nonReentrant {
        require(fund.cyclePhase() == 1, "wrong phase");
        require(fund.isInitialized(), "fund not initialized");
        uint256 peakPrice = _getPeakPrice();
        uint256 comp = _calculateCompensating(msg.sender, peakPrice);
        require(comp == 0, "have compensation");
        require(amount > 0, "amount is 0");
        sharesToken.safeTransferFrom(msg.sender, address(this), amount);
        startProtectTimestamp[msg.sender] = block.timestamp;
        shares[msg.sender] = shares[msg.sender].add(amount);
        _syncLastClaimAmount();
        emit ProtectShares(msg.sender, amount, block.timestamp);
    }

    function withdrawShares(uint256 amount) public nonReentrant {
        uint256 peakPrice = _getPeakPrice();
        uint256 comp = _calculateCompensating(msg.sender, peakPrice);
        require(comp == 0, "have compensation");
        require(shares[msg.sender] >= amount, "insufficient fund in Share Token");
        require(amount > 0, "amount is 0");
        shares[msg.sender] = shares[msg.sender].sub(amount);
        sharesToken.safeTransfer(msg.sender, amount);
        emit WithdrawShares(msg.sender, amount, block.timestamp);
    }

    function requestProtection(uint256 amount) public {
        require(fund.cyclePhase() == 1, "wrong phase");
        require(fund.isInitialized(), "fund not initialized");
        uint256 peakPrice = _getPeakPrice();
        uint256 comp = _calculateCompensating(msg.sender, peakPrice);
        require(comp == 0, "have compensation");
        require(amount > 0, "amount is 0");
        peakToken.safeTransferFrom(msg.sender, address(this), amount);
        peaks[msg.sender] = peaks[msg.sender].add(amount);
        startProtectTimestamp[msg.sender] = block.timestamp;
        _syncLastClaimAmount();
        emit RequestProtection(msg.sender, amount, block.timestamp);
    }

    function withdraw(uint256 amount) public {
        uint256 peakPrice = _getPeakPrice();
        uint256 comp = _calculateCompensating(msg.sender, peakPrice);
        require(comp == 0, "have compensation");
        require(peaks[msg.sender] >= amount, "insufficient fund in Peak Token");
        require(amount > 0, "amount is 0");
        peaks[msg.sender] = peaks[msg.sender].sub(amount);
        peakToken.safeTransfer(msg.sender, amount);
        _syncLastClaimAmount();
        emit Withdraw(msg.sender, amount, block.timestamp);
    }

    function claimCompensation() public nonReentrant {
        require(fund.cyclePhase() == 1, "wrong phase");
        require(fund.isInitialized(), "fund not initialized");
        uint256 peakPrice = _getPeakPrice();
        uint256 comp = _calculateCompensating(msg.sender, peakPrice);
        require(comp > 0, "not have compensation");
        startClaimTimestamp[msg.sender] = block.timestamp;
        IMintable(address(peakToken)).mint(msg.sender, comp);
        mintedPeakTokens = mintedPeakTokens.add(comp);
        require(mintedPeakTokens <= peakMintCap, "ProtectionStaking: reached cap");
        _syncLastClaimAmount();
        emit ClaimCompensation(msg.sender, comp, block.timestamp);
    }

    function calculateCompensating(address user, uint256 peakTokenPrice) public view returns (uint256) {
        return _calculateCompensating(user, peakTokenPrice);
    }

    function _getPeakPrice() internal returns (uint256) {
        uniswapOracle.update();
        uint256 price = uniswapOracle.consult(address(peakToken), PEAK_PRECISION);
        if (price == 0) {
            return uint256(3).mul(1e6).div(10);
        }
        return price;
    }

    function _syncLastClaimAmount() internal {
        lastClaimAmount[msg.sender] = fund.totalLostFundAmount();
    }

    function _calculateCompensating(address user, uint256 peakPrice) internal view returns (uint256) {
        uint256 phase = fund.cyclePhase();
        uint256 totalShares = fund.totalSharesAtLastManagePhaseStart();
        uint256 lastPhaseStart = fund.startTimeOfLastManagementPhase();
        uint256 totalLost = fund.totalLostFundAmount();
        uint256 pending = totalLost.sub(lastClaimAmount[user]);
        uint256 userShares = shares[user];

        if (phase != 1
            || startClaimTimestamp[user] < lastPhaseStart
            || startProtectTimestamp[user] < lastPhaseStart
            || mintedPeakTokens >= peakMintCap
            || peaks[user] == 0
            || userShares == 0
            || totalShares == 0
            || pending == 0
            || peakPrice == 0) {
            return 0;
        }

        uint256 shareValue = userShares.mul(pending).div(totalShares);
        if (shareValue > MAX_SHARE_VALUE) {
            shareValue = MAX_SHARE_VALUE;
        }
        uint256 peakAmount = shareValue.mul(SHARE_PRECISION).div(peakPrice);
        uint256 remainingCap = peakMintCap.sub(mintedPeakTokens);
        if (peakAmount > remainingCap) {
            peakAmount = remainingCap;
        }
        return peakAmount;
    }
}
