        address _pool
    ) public {
        farmInternal = _farm;
        feeRecipient = _feeRecipient;
        harvester = _harvester;
        stakingToken = _stakingToken;
        pool = _pool;
        _setupRole(DEFAULT_ADMIN_ROLE, msg.sender);
    }

    modifier onlyFarm() {
        require(farmInternal == msg.sender, "!farm");
        _;
    }
    modifier onlyHarvesterAddr() {
        require(harvester == msg.sender, "!auth");
        _;
    }
    modifier onlyAdmin() {
        require(hasRole(ADMIN_ROLE, msg.sender), "!admin");
        _;
    }
    modifier onlyExtract() {
        require(hasRole(EXTRACT_ROLE, msg.sender), "!extract");
        _;
    }
    modifier onlyMinter() {
        require(hasRole(MINTER_ROLE, msg.sender), "!minter");
        _;
    }
    modifier onlyDefaultAdmin() {
        require(hasRole(DEFAULT_ADMIN_ROLE, msg.sender),
            "AccessControl: sender must be an admin to grant");
        _;
    }
    modifier onlyHarvesterRole() {
        require(hasRole(HARVESTER_ROLE, msg.sender),
            "AccessControl: sender must be an admin to grant");
        _;
    }

    function rewardAdded(address token) external onlyFarm nonReentrant {
        _addRewardToken(token);
        IFarm(harvester).rewardAdded(token);
    }

    function withdraw(uint256 amount) external onlyHarvesterAddr nonReentrant {
        IPool(pool).withdraw(amount);
        uint256 bal = IERC20(stakingToken).balanceOf(address(this));
        IERC20(stakingToken).safeTransfer(harvester, bal);
    }

    function harvest() external onlyHarvesterAddr nonReentrant {
        IPool(pool).getReward();
        for (uint256 i = 0; i < _allRewards.length; i++) {
            address token = _allRewards[i];
            uint256 bal = IERC20(token).balanceOf(address(this));
            if (bal > 0) {
                uint256 fee = _collectFee(feeRecipient, token, bal);
                IERC20(token).safeTransfer(harvester, bal - fee);
            }
        }
    }

    function _collectFee(address fc, address token, uint256 bal) internal returns (uint256 fee) {
        fee = IFeeCollector(fc).rewardFee(bal);
        if (fee > 0) {
            address to = IFeeCollector(fc).reward();
            require(to != address(0));
            IERC20(token).safeTransfer(to, fee);
        }
    }

    function earn() external onlyHarvesterAddr nonReentrant {
        uint256 bal = IERC20(stakingToken).balanceOf(address(this));
        IERC20(stakingToken).safeApprove(pool, 0);
        IERC20(stakingToken).safeApprove(pool, bal * 2);
        if (bal > 0) {
            IPool(pool).stake(bal);
        }
    }

    function getFarm() external view returns (address) {
        return farmInternal;
    }

    function setFarm(address newFarm) external onlyAdmin {
        farmInternal = newFarm;
        address[] memory r = IFarm(newFarm).rewards();
        for (uint256 i = 0; i < r.length; i++) {
            _addRewardToken(r[i]);
        }
    }

    function rewardTotals() external view returns (address[] memory) {
        return _allRewards;
    }

    function addReward(address token) external onlyDefaultAdmin {
        _addRewardToken(token);
    }

    function extractStuckTokens(address token, address to) external onlyExtract {
        require(token != address(0) || to != address(0));
        uint256 bal = IERC20(token).balanceOf(address(this));
        if (bal > 0) {
            IERC20(token).safeTransfer(to, bal);
        }
    }

    function setupRoles(address adminAcct, address extractAcct, address defaultAdminAcct)
        external onlyDefaultAdmin
    {
        _setupRole(ADMIN_ROLE, adminAcct);
        _setupRole(EXTRACT_ROLE, extractAcct);
        _setupRole(DEFAULT_ADMIN_ROLE, defaultAdminAcct);
    }

    function setupAdmin(address account) external onlyAdmin {
        _setupRole(ADMIN_ROLE, account);
    }

    function setupExtract(address account) external onlyExtract {
        _setupRole(EXTRACT_ROLE, account);
    }

    function setupMinter(address account) external onlyMinter {
        _setupRole(MINTER_ROLE, account);
    }

    function setupDefaultAdmin(address account) external onlyDefaultAdmin {
        _setupRole(DEFAULT_ADMIN_ROLE, account);
    }

    function setupHarvester(address account) external onlyHarvesterRole {
        _setupRole(HARVESTER_ROLE, account);
    }
}
